begin;
select no_plan();
create temp table guard_fixture(key text primary key,value jsonb);
grant all on guard_fixture to authenticated;
delete from public.membership_permission where membership_id='40000000-0000-0000-0000-000000000002' and membership_permission_admin_permission<>'guards';
select set_config('request.jwt.claims','{"sub":"20000000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal1"}',true);
set local role authenticated;
select is(jsonb_array_length(public.list_tenant_guards('10000000-0000-0000-0000-000000000001')->'guards'),1,'Guards-only admin lists own guards');
select is(public.list_tenant_guards('10000000-0000-0000-0000-000000000001')->'guards'->0->'gates'->0->>'gate_id','d1000000-0000-0000-0000-000000000001','Assigned gate is projected');
select is((select array_agg(k order by k) from jsonb_object_keys(public.list_tenant_guards('10000000-0000-0000-0000-000000000001')->'guards'->0) k),array['gates','membership_id','membership_status','membership_valid_from','membership_valid_to','person_email','person_first_name','person_id','person_last_name'],'Guard projection has only allowed fields');
select is((select array_agg(k order by k) from jsonb_object_keys(public.list_tenant_guards('10000000-0000-0000-0000-000000000001')->'pending_invitations'->0) k),array['invitation_delivered_at','invitation_email','invitation_expires_at','invitation_first_name','invitation_id','invitation_last_name','invitation_status'],'Invitation projection excludes secrets and resident data');
select is((select count(*) from public.person where tenant_id='10000000-0000-0000-0000-000000000001' and person_id<>'30000000-0000-0000-0000-000000000002'),0::bigint,'Guards-only admin cannot read other person rows');
select is((select count(*) from public.unit where tenant_id='10000000-0000-0000-0000-000000000001' ),0::bigint,'Guards-only admin cannot read other unit rows');
select is((select count(*) from public.unit_resident where tenant_id='10000000-0000-0000-0000-000000000001' ),0::bigint,'Guards-only admin cannot read other unit_resident rows');
select is((select count(*) from public.person where person_id='30000000-0000-0000-0000-000000000003' and (person_document_number is not null or person_birth_date is not null)),0::bigint,'Guard document and birthday remain hidden');
select throws_ok($$select public.list_tenant_guards('10000000-0000-0000-0000-000000000002')$$,'42501','Guard management denied','Foreign tenant list denied');
select throws_ok($$select public.list_tenant_guards('10000000-0000-0000-0000-000000009999')$$,'42501','Guard management denied','Missing tenant list denied');
select throws_ok($$select public.revoke_membership('40000000-0000-0000-0000-000000000007')$$,'42501','Membership management denied','Foreign guard deactivation denied');
select throws_ok($$select public.revoke_membership('40000000-0000-0000-0000-000000000004')$$,'42501','Membership management denied','Non-guard or missing deactivation denied');
select throws_ok($$select public.revoke_membership('40000000-0000-0000-0000-000000000002')$$,'42501','Membership management denied','Non-guard or missing deactivation denied');
select throws_ok($$select public.revoke_membership('40000000-0000-0000-0000-000000009999')$$,'42501','Membership management denied','Non-guard or missing deactivation denied');
select lives_ok($$select public.save_gate('10000000-0000-0000-0000-000000000001','{"gate_name":"T21 gate","gate_kind":"pedestrian"}',gen_random_uuid())$$,'Guards-only admin manages gates');
select lives_ok($$select public.assign_guard_gate('10000000-0000-0000-0000-000000000001','d1000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000003',false,gen_random_uuid())$$,'Guards-only admin removes assignment');
select lives_ok($$select public.assign_guard_gate('10000000-0000-0000-0000-000000000001','d1000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000003',true,gen_random_uuid())$$,'Guards-only admin adds assignment');
select lives_ok($$select public.create_device_pairing('10000000-0000-0000-0000-000000000001','d1000000-0000-0000-0000-000000000001',gen_random_uuid())$$,'Guards-only admin creates device pairing');
select lives_ok($$select public.revoke_device('10000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001',gen_random_uuid())$$,'Guards-only admin revokes device');
select throws_ok($$select public.create_invitation('10000000-0000-0000-0000-000000000001','t21.new@example.test','tenant_admin',gen_random_uuid())$$,'42501','Invitation management denied','Guards cannot invite tenant_admin');
select throws_ok($$select public.create_invitation('10000000-0000-0000-0000-000000000001','t21.new@example.test','unit_holder',gen_random_uuid())$$,'42501','Invitation management denied','Guards cannot invite unit_holder');
select throws_ok($$select public.create_invitation('10000000-0000-0000-0000-000000000001','t21.new@example.test','household_member',gen_random_uuid())$$,'42501','Invitation management denied','Guards cannot invite household_member');
select throws_ok($$select public.create_invitation('10000000-0000-0000-0000-000000000002','t21.new@example.test','guard',gen_random_uuid())$$,'42501','Invitation management denied','Cross tenant guard invitation denied');
select throws_ok($$select public.create_invitation('10000000-0000-0000-0000-000000000001','t21.new@example.test','guard',gen_random_uuid(),'30000000-0000-0000-0000-000000000005')$$,'42501','Invitation management denied','Guard invitation cannot target resident');
select throws_ok($$select public.create_invitation('10000000-0000-0000-0000-000000000001','t21.new@example.test','guard',gen_random_uuid(),null,null,null,array['guards']::public.admin_permission[])$$,'42501','Invitation management denied','Guard invitation cannot carry permissions');
select lives_ok($$insert into guard_fixture select 'invitation',to_jsonb(i) from public.create_invitation('10000000-0000-0000-0000-000000000001','t21.new@example.test','guard',gen_random_uuid(),null,'New','Guard') i$$,'Guards-only admin invites guard');
select lives_ok($$select public.mark_invitation_delivered((select (value->>'invitation_id')::uuid from guard_fixture where key='invitation'))$$,'Guards-only admin marks delivery');
select lives_ok($$select public.revoke_invitation((select (value->>'invitation_id')::uuid from guard_fixture where key='invitation'))$$,'Guards-only admin cancels guard invitation');
select lives_ok($$insert into guard_fixture select 'accept',to_jsonb(i) from public.create_invitation('10000000-0000-0000-0000-000000000001','t21.accept@example.test','guard',gen_random_uuid(),null,'Accepted','Guard') i$$,'Guards-only admin issues acceptance fixture');
reset role;
insert into auth.users(instance_id,id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values('00000000-0000-0000-0000-000000000000','20000000-0000-0000-0000-000000000021','authenticated','authenticated','t21.accept@example.test',now(),'{"provider":"email","providers":["email"]}','{}',now(),now());
select set_config('request.jwt.claims',jsonb_build_object('sub','20000000-0000-0000-0000-000000000021','role','authenticated','aal','aal1','amr',jsonb_build_array(jsonb_build_object('method','otp','timestamp',floor(extract(epoch from statement_timestamp())))))::text,true);
set local role authenticated;
select lives_ok($$select public.accept_invitation((select value->>'invitation_token' from guard_fixture where key='accept'))$$,'Invitee accepts guards-only grantor invitation');
reset role;
select set_config('request.jwt.claims','{"sub":"20000000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal1"}',true);
set local role authenticated;
select lives_ok($$select public.revoke_membership((select (g->>'membership_id')::uuid from jsonb_array_elements(public.list_tenant_guards('10000000-0000-0000-0000-000000000001')->'guards') g where g->>'person_first_name'='Accepted'))$$,'Guards-only admin directly deactivates accepted guard');
select is((select g->>'membership_status' from jsonb_array_elements(public.list_tenant_guards('10000000-0000-0000-0000-000000000001')->'guards') g where g->>'person_first_name'='Accepted'),'revoked','Direct deactivation appears in list');
select throws_ok($$select public.assign_guard_gate('10000000-0000-0000-0000-000000000001','d2000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000003',true,gen_random_uuid())$$,'42501','Gate management denied','Foreign gate assignment denied');
select throws_ok($$select public.revoke_device('10000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001',gen_random_uuid())$$,'42501','Device management denied','Foreign device revocation denied');
select throws_ok($$select public.grant_admin_permission('40000000-0000-0000-0000-000000000002','registry')$$,'42501','Membership management denied','Guards-only admin cannot grant registry');
reset role;
update public.tenant set tenant_subscription_status='suspended' where tenant_id='10000000-0000-0000-0000-000000000001';
select set_config('request.jwt.claims','{"sub":"20000000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal1"}',true);
set local role authenticated;
select lives_ok($$select public.list_tenant_guards('10000000-0000-0000-0000-000000000001')$$,'Suspended tenant allows minimized read');
select throws_ok($$select public.revoke_membership('40000000-0000-0000-0000-000000000003')$$,'42501','Membership management denied','Suspended guard deactivation denied');
select throws_ok($$select public.create_invitation('10000000-0000-0000-0000-000000000001','t21.suspended@example.test','guard',gen_random_uuid())$$,'42501','Invitation management denied','Suspended guard invitation denied');
select throws_ok($$select public.save_gate('10000000-0000-0000-0000-000000000001','{}',gen_random_uuid())$$,'42501','Gate management denied','Suspended gate write denied');
select throws_ok($$select public.assign_guard_gate('10000000-0000-0000-0000-000000000001','d1000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000003',false,gen_random_uuid())$$,'42501','Gate management denied','Suspended assignment denied');
select throws_ok($$select public.create_device_pairing('10000000-0000-0000-0000-000000000001','d1000000-0000-0000-0000-000000000001',gen_random_uuid())$$,'42501','Gate management denied','Suspended pairing denied');
select throws_ok($$select public.revoke_device('10000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001',gen_random_uuid())$$,'42501','Gate management denied','Suspended device revocation denied');
reset role;
update public.tenant set tenant_subscription_status='active' where tenant_id='10000000-0000-0000-0000-000000000001';
insert into public.person(person_id,tenant_id,user_id,person_first_name,person_last_name) values('30000000-0000-0000-0000-000000000021','10000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000002','Support','Admin');
insert into public.membership(membership_id,tenant_id,person_id,membership_role,membership_valid_from) values('40000000-0000-0000-0000-000000000021','10000000-0000-0000-0000-000000000002','30000000-0000-0000-0000-000000000021','tenant_admin','2020-01-01');
insert into public.membership_permission(tenant_id,membership_id,membership_permission_admin_permission) values('10000000-0000-0000-0000-000000000002','40000000-0000-0000-0000-000000000021','guards');
select set_config('request.jwt.claims','{"sub":"20000000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal1","x":"x"}',true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"20000000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal2"}',true);
insert into guard_fixture values('support',to_jsonb(public.start_support_session('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000002','T21 guards binding',gen_random_uuid())));
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub','20000000-0000-0000-0000-000000000002','role','authenticated','aal','aal1','session_id',(select value->>'support_session_id' from guard_fixture where key='support'),'support_session_id',(select value->>'support_session_id' from guard_fixture where key='support'),'support_tenant_id','10000000-0000-0000-0000-000000000001','impersonator_user_id','20000000-0000-0000-0000-000000000001','impersonator_aal','aal2','exp',floor(extract(epoch from((select value->>'support_session_expires_at' from guard_fixture where key='support')::timestamptz))))::text,true);
set local role authenticated;
select ok(app_private.current_identity_is_valid(),'Support identity valid');
select lives_ok($$select public.list_tenant_guards('10000000-0000-0000-0000-000000000001')$$,'Support can list within binding');
select throws_ok($$select public.list_tenant_guards('10000000-0000-0000-0000-000000000002')$$,'42501','Guard management denied','Support cannot use target user foreign guards authority');
select throws_ok($$select public.revoke_membership('40000000-0000-0000-0000-000000000007')$$,'42501','Membership management denied','Support foreign revocation denied');
select throws_ok($$select public.create_invitation('10000000-0000-0000-0000-000000000001','t21.support@example.test','guard',gen_random_uuid())$$,'42501','Invitation management denied','Support invitation issuance remains prohibited');
select lives_ok($$select public.revoke_membership('40000000-0000-0000-0000-000000000003')$$,'Support deactivates guard within binding');
reset role;
select is((select membership_status::text from public.membership where membership_id='40000000-0000-0000-0000-000000000003'),'revoked','Guard deactivated');
select ok(exists(select 1 from public.audit_event where audit_event_row_id='40000000-0000-0000-0000-000000000003' and audit_event_actor_user_id='20000000-0000-0000-0000-000000000001' and audit_event_on_behalf_of_user_id='20000000-0000-0000-0000-000000000002' and audit_event_diff->'membership_status'->>'new'='revoked'),'Support deactivation attributed to actor and target');
select set_config('request.jwt.claims','{"sub":"20000000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal1","support_session_id":"invalid"}',true);
set local role authenticated;
select throws_ok($$select public.list_tenant_guards('10000000-0000-0000-0000-000000000001')$$,'42501','Guard management denied','Malformed support identity denied');
reset role;
update public.membership_permission set membership_permission_admin_permission='registry' where membership_id='40000000-0000-0000-0000-000000000002';
select set_config('request.jwt.claims','{"sub":"20000000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal1"}',true);
set local role authenticated;
select lives_ok($$select public.list_tenant_guards('10000000-0000-0000-0000-000000000001')$$,'Registry-only admin retains guard list');
select is((select count(*) from public.unit where tenant_id='10000000-0000-0000-0000-000000000001'),40::bigint,'Registry-only unit reads unchanged');
select lives_ok($$select public.create_invitation('10000000-0000-0000-0000-000000000001','t21.registry@example.test','guard',gen_random_uuid())$$,'Registry-only guard invitation unchanged');
select lives_ok($$select public.revoke_membership('40000000-0000-0000-0000-000000000003')$$,'Registry-only guard deactivation unchanged');
select throws_ok($$select public.save_gate('10000000-0000-0000-0000-000000000001','{}',gen_random_uuid())$$,'42501','Gate management denied','Registry-only does not gain gate permission');
reset role;
select ok(not has_function_privilege('anon','public.list_tenant_guards(uuid)','EXECUTE'),'anon cannot execute guard list');
select ok(not has_function_privilege('service_role','public.list_tenant_guards(uuid)','EXECUTE'),'service_role cannot execute guard list');
select * from finish();
rollback;
